@Override
public E next() {
    if (this.next != null) {
        E current = this.next;
        this.next = this.advanceToNext();
        // PATH: Test should invoke the next KryoSerializer.copy(...) [step in execution path]
        return serializer.copy(current);
    } else {
        throw new NoSuchElementException();
    }
}

@SuppressWarnings("unchecked")
@Override
public T copy(T from) {
    if (from == null) {
        return null;
    }
    if (CONCURRENT_ACCESS_CHECK) {
        enterExclusiveThread();
    }
    try {
        checkKryoInitialized();
        try {
            // PATH: Test should invoke the next Kryo.copy(...) [step in execution path]
            return kryo.copy(from);
        } catch (KryoException ke) {
            // kryo was unable to copy it, so we do it through serialization:
            ByteArrayOutputStream baout = new ByteArrayOutputStream();
            Output output = new Output(baout);
            kryo.writeObject(output, from);
            output.close();
            ByteArrayInputStream bain = new ByteArrayInputStream(baout.toByteArray());
            Input input = new Input(bain);
            return ((T) (kryo.readObject(input, from.getClass())));
        }
    } finally {
        if (CONCURRENT_ACCESS_CHECK) {
            exitExclusiveThread();
        }
    }
}

