private void checkKryoInitialized() {
    if (this.kryo == null) {
        // PATH: Test should invoke the next KryoSerializer.getKryoInstance(...) [step in execution path]
        this.kryo = getKryoInstance();
        // Enable reference tracking.
        kryo.setReferences(true);
        // Throwable and all subclasses should be serialized via java serialization
        // Note: the registered JavaSerializer is Flink's own implementation, and not Kryo's.
        // This is due to a know issue with Kryo's JavaSerializer. See FLINK-6025 for
        // details.
        kryo.addDefaultSerializer(Throwable.class, new JavaSerializer());
        // Add default serializers first, so that the type registrations without a serializer
        // are registered with a default serializer
        for (Map.Entry<Class<?>, SerializableSerializer<?>> entry : defaultSerializers.entrySet()) {
            kryo.addDefaultSerializer(entry.getKey(), entry.getValue().getSerializer());
        }
        for (Map.Entry<Class<?>, Class<? extends Serializer<?>>> entry : defaultSerializerClasses.entrySet()) {
            kryo.addDefaultSerializer(entry.getKey(), entry.getValue());
        }
        KryoUtils.applyRegistrations(this.kryo, kryoRegistrations.values(), flinkChillPackageRegistrar != null ? flinkChillPackageRegistrar.getNextRegistrationId() : kryo.getNextRegistrationId());
        kryo.setRegistrationRequired(false);
