public KryoSerializer(Class<T> type, SerializerConfig serializerConfig) {
    this.type = checkNotNull(type);
    this.defaultSerializers = ((SerializerConfigImpl) (serializerConfig)).getDefaultKryoSerializers();
    this.defaultSerializerClasses = serializerConfig.getDefaultKryoSerializerClasses();
    this.kryoRegistrations = buildKryoRegistrations(this.type, serializerConfig.getRegisteredKryoTypes(), serializerConfig.getRegisteredTypesWithKryoSerializerClasses(), ((SerializerConfigImpl) (serializerConfig)).getRegisteredTypesWithKryoSerializers(), serializerConfig.isForceKryoAvroEnabled());
}

/**
 * Copy-constructor that does not copy transient fields. They will be initialized once required.
 */
protected KryoSerializer(KryoSerializer<T> toCopy) {
    this.type = checkNotNull(toCopy.type, "Type class cannot be null.");
    this.defaultSerializerClasses = toCopy.defaultSerializerClasses;
    this.defaultSerializers = CollectionUtil.newLinkedHashMapWithExpectedSize(toCopy.defaultSerializers.size());
    this.kryoRegistrations = CollectionUtil.newLinkedHashMapWithExpectedSize(toCopy.kryoRegistrations.size());
    // deep copy the serializer instances in defaultSerializers
    for (Map.Entry<Class<?>, SerializableSerializer<?>> entry : toCopy.defaultSerializers.entrySet()) {
        this.defaultSerializers.put(entry.getKey(), deepCopySerializer(entry.getValue()));
    }
    // deep copy the serializer instances in kryoRegistrations
    for (Map.Entry<String, KryoRegistration> entry : toCopy.kryoRegistrations.entrySet()) {
        KryoRegistration kryoRegistration = entry.getValue();
        if (kryoRegistration.getSerializerDefinitionType() == KryoRegistration.SerializerDefinitionType.INSTANCE) {
            SerializableSerializer<? extends Serializer<?>> serializerInstance = kryoRegistration.getSerializableSerializerInstance();
            if (serializerInstance != null) {
                kryoRegistration = new KryoRegistration(kryoRegistration.getRegisteredClass(), deepCopySerializer(serializerInstance));
            }
        }
        this.kryoRegistrations.put(entry.getKey(), kryoRegistration);
    }
}

