@Override
@SuppressWarnings({ "unchecked", "rawtypes" })
public T deserialize(DataInputView source) throws IOException {
    int flags = source.readByte();
    if ((flags & IS_NULL) != 0) {
        return null;
    }
    T target;
    Class<?> actualSubclass = null;
    TypeSerializer subclassSerializer = null;
    if ((flags & IS_SUBCLASS) != 0) {
        String subclassName = source.readUTF();
        actualSubclass = getSubclassByName(subclassName);
        subclassSerializer = getSubclassSerializer(actualSubclass);
        target = ((T) (subclassSerializer.createInstance()));
        // also initialize fields for which the subclass serializer is not responsible
        initializeFields(target);
    } else if ((flags & IS_TAGGED_SUBCLASS) != 0) {
        int subclassTag = source.readByte();
        subclassSerializer = registeredSerializers[subclassTag];
        target = ((T) (subclassSerializer.createInstance()));
        // also initialize fields for which the subclass serializer is not responsible
        initializeFields(target);
    } else {
        target = createInstance();
    }
    if (isRecord()) {
        JavaRecordBuilderFactory<T>.JavaRecordBuilder builder = recordFactory.newBuilder();
        for (int i = 0; i < numFields; i++) {
            boolean isNull = source.readBoolean();
            // PATH: Test should invoke the next KryoSerializer.deserialize(...) [step in execution path]
            Object fieldValue = (isNull) ? null : fieldSerializers[i].deserialize(source);
            if (fields[i] != null) {
                builder.setField(i, fieldValue);
            }
        }
        target = builder.build();
    } else if ((flags & NO_SUBCLASS) != 0) {
        try {
            for (int i = 0; i < numFields; i++) {
                boolean isNull = source.readBoolean();
                Object fieldValue = (isNull) ? null : fieldSerializers[i].deserialize(source);
                if (fields[i] != null) {
                    fields[i].set(target, fieldValue);
                }
            }
        } catch (IllegalAccessException e) {
            throw new RuntimeException("Error during POJO copy, this should not happen since we check the fields before.", e);
        }
    } else if (subclassSerializer != null) {
        target = ((T) (subclassSerializer.deserialize(target, source)));
    }
    return target;
}

@SuppressWarnings("unchecked")
@Override
public T deserialize(DataInputView source) throws IOException {
    if (CONCURRENT_ACCESS_CHECK) {
        enterExclusiveThread();
    }
    try {
        checkKryoInitialized();
        if (source != previousIn) {
            DataInputViewStream inputStream = new DataInputViewStream(source);
            input = new NoFetchingInput(inputStream);
            previousIn = source;
        }
        try {
            // PATH: Test should invoke the next Kryo.readClassAndObject(...) [step in execution path]
            return ((T) (kryo.readClassAndObject(input)));
        } catch (KryoBufferUnderflowException ke) {
            // 2023-04-26: Existing Flink code expects a java.io.EOFException in this scenario
            throw new EOFException(ke.getMessage());
        } catch (KryoException ke) {
            Throwable cause = ke.getCause();
            if (cause instanceof EOFException) {
                throw ((EOFException) (cause));
            } else {
