public static void extractFile(String srcFilePath, String targetDirPath, String originalFileName) throws IOException {
    if (hasOneOfSuffixes(originalFileName, ".zip", ".jar")) {
        extractZipFileWithPermissions(srcFilePath, targetDirPath);
    } else if (hasOneOfSuffixes(originalFileName, ".tar", ".tar.gz", ".tgz")) // PATH: Test should invoke the next CompressionUtils.extractTarFile(...) [step in execution path]
    {
        extractTarFile(srcFilePath, targetDirPath);
    } else {
        LOG.warn("Only zip, jar, tar, tgz and tar.gz suffixes are supported, found {}. Trying to extract it as zip file.", originalFileName);
        extractZipFileWithPermissions(srcFilePath, targetDirPath);
    }
}

public static void extractTarFile(String inFilePath, String targetDirPath) throws IOException {
    final File targetDir = new File(targetDirPath);
    if (!targetDir.mkdirs()) {
        if (!targetDir.isDirectory()) {
            throw new IOException("Mkdirs failed to create " + targetDir);
        }
    }
    final boolean gzipped = inFilePath.endsWith("gz");
    if (isUnix()) {
        extractTarFileUsingTar(inFilePath, targetDirPath, gzipped);
    } else // PATH: Test should invoke the next CompressionUtils.extractTarFileUsingJava(...) [step in execution path]
    {
        extractTarFileUsingJava(inFilePath, targetDirPath, gzipped);
    }
}

// Follow the pattern suggested in
// https://commons.apache.org/proper/commons-compress/examples.html
private static void extractTarFileUsingJava(String inFilePath, String targetDirPath, boolean gzipped) throws IOException {
    try (InputStream fi = Files.newInputStream(Paths.get(inFilePath));InputStream bi = new BufferedInputStream(fi);final TarArchiveInputStream tai = new TarArchiveInputStream(gzipped ? new GzipCompressorInputStream(bi) : bi)) {
        final File targetDir = new File(targetDirPath);
        TarArchiveEntry entry;
        while ((entry = tai.getNextTarEntry()) != null) // PATH: Test should invoke the next CompressionUtils.unpackEntry(...) [step in execution path]
        {
            unpackEntry(tai, entry, targetDir);
        } 
    }
}

private static void unpackEntry(TarArchiveInputStream tis, TarArchiveEntry entry, File targetDir) throws IOException {
    String targetDirPath = targetDir.getCanonicalPath() + File.separator;
    File outputFile = new File(targetDir, entry.getName());
    if (!outputFile.getCanonicalPath().startsWith(targetDirPath)) {
        throw new IOException((("expanding " + entry.getName()) + " would create entry outside of ") + targetDir);
    }
    if (entry.isDirectory()) {
        if ((!outputFile.mkdirs()) && (!outputFile.isDirectory())) {
            throw new IOException("Failed to create directory " + outputFile);
        }
        for (TarArchiveEntry e : entry.getDirectoryEntries()) {
            CompressionUtils.unpackEntry(tis, e, outputFile);
        }
        return;
    }
    // PATH: Test should invoke the next TarArchiveEntry.isSymbolicLink(...) [step in execution path]
    if (entry.isSymbolicLink()) {
        // create symbolic link relative to tar parent dir
        Files.createSymbolicLink(Paths.get(new File(targetDir, entry.getName()).getCanonicalPath()), Paths.get(entry.getLinkName()));
        return;
    }
    if (!outputFile.getParentFile().exists()) {
        if (!outputFile.getParentFile().mkdirs()) {
            throw new IOException("Mkdirs failed to create tar internal dir " + targetDir);
        }
    }
    try (OutputStream o = Files.newOutputStream(Paths.get(outputFile.getCanonicalPath()))) {
        IOUtils.copyBytes(tis, o, false);
    }
}

