public T copy(T from, T reuse) {
    if (from == null) {
        return null;
    }
    Class<?> actualType = from.getClass();
    if ((reuse == null) || (actualType != reuse.getClass())) {
        // cannot reuse, do a non-reuse copy
        return copy(from);
