public TypeSerializerSchemaCompatibility<T> resolveSchemaCompatibility(TypeSerializerSnapshot<T> oldSerializerSnapshot) {
    if (!(oldSerializerSnapshot instanceof PojoSerializerSnapshot)) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    PojoSerializerSnapshot<T> previousPojoSerializerSnapshot = ((PojoSerializerSnapshot<T>) (oldSerializerSnapshot));
    final Class<T> previousPojoClass = previousPojoSerializerSnapshot.snapshotData.getPojoClass();
    final LinkedOptionalMap<Field, TypeSerializerSnapshot<?>> fieldSerializerSnapshots = previousPojoSerializerSnapshot.snapshotData.getFieldSerializerSnapshots();
    final LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>> registeredSubclassSerializerSnapshots = previousPojoSerializerSnapshot.snapshotData.getRegisteredSubclassSerializerSnapshots();
    final LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>> nonRegisteredSubclassSerializerSnapshots = previousPojoSerializerSnapshot.snapshotData.getNonRegisteredSubclassSerializerSnapshots();
    if (previousPojoClass != snapshotData.getPojoClass()) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    if (registeredSubclassSerializerSnapshots.hasAbsentKeysOrValues()) {
