private IntermediateCompatibilityResult<T> getCompatibilityOfPreExistingFields(LinkedOptionalMap<Field, TypeSerializerSnapshot<?>> oldFieldSerializerSnapshots) {
    // the present entries dictates the preexisting fields, because removed fields would be
    // represented as absent keys in the optional map.
    final Set<LinkedOptionalMap.KeyValue<Field, TypeSerializerSnapshot<?>>> presentFieldSnapshots = oldFieldSerializerSnapshots.getPresentEntries();
    final ArrayList<TypeSerializerSnapshot<?>> associatedFieldSerializerSnapshots = new ArrayList<>(presentFieldSnapshots.size());
    final ArrayList<TypeSerializerSnapshot<?>> associatedNewFieldSerializerSnapshots = new ArrayList<>(presentFieldSnapshots.size());
    Map<Field, TypeSerializerSnapshot<?>> newFieldSerializerSnapshots = snapshotData.getFieldSerializerSnapshots().unwrapOptionals();
    for (LinkedOptionalMap.KeyValue<Field, TypeSerializerSnapshot<?>> presentFieldEntry : presentFieldSnapshots) {
        TypeSerializerSnapshot<?> associatedNewFieldSerializer = newFieldSerializerSnapshots.get(presentFieldEntry.getKey());
        checkState(associatedNewFieldSerializer != null, "a present field should have its associated new field serializer available.");
        associatedFieldSerializerSnapshots.add(presentFieldEntry.getValue());
        associatedNewFieldSerializerSnapshots.add(associatedNewFieldSerializer);
