private TypeSerializerSchemaCompatibility<T> resolveSchemaCompatibility(KryoSerializerSnapshot<T> oldKryoSerializerSnapshot) {
    // merge the default serializers
    final MergeResult<Class<?>, SerializableSerializer<?>> reconfiguredDefaultKryoSerializers = mergeRightIntoLeft(oldKryoSerializerSnapshot.snapshotData.getDefaultKryoSerializers(), snapshotData.getDefaultKryoSerializers());
    if (reconfiguredDefaultKryoSerializers.hasMissingKeys()) {
