    // merge default serializer classes
    final MergeResult<Class<?>, Class<? extends Serializer<?>>> reconfiguredDefaultKryoSerializerClasses = mergeRightIntoLeft(oldKryoSerializerSnapshot.snapshotData.getDefaultKryoSerializerClasses(), snapshotData.getDefaultKryoSerializerClasses());
    if (reconfiguredDefaultKryoSerializerClasses.hasMissingKeys()) {
