    }
    // merge registration
    final MergeResult<String, KryoRegistration> reconfiguredRegistrations = mergeRightIntoLeft(oldKryoSerializerSnapshot.snapshotData.getKryoRegistrations(), snapshotData.getKryoRegistrations());
    if (reconfiguredRegistrations.hasMissingKeys()) {
