    // require reconfiguration.
    // PATH: Test should invoke the next KryoSerializerSnapshot.resolveSchemaCompatibility(...) [step in execution path]
    return resolveSchemaCompatibility(reconfiguredDefaultKryoSerializers, reconfiguredDefaultKryoSerializerClasses, reconfiguredRegistrations);
